index be73e321..f0231a22 100644
--- a/src/main/java/org/jsoup/nodes/Entities.java
+++ b/src/main/java/org/jsoup/nodes/Entities.java
@@ -100,27 +100,39 @@ public class Entities {
      * @return
      */
     static String unescape(String string, boolean strict) {
+        if (string.contains("mid") || string.contains("wr")) System.err.println("DEBUG unescape: string='" + string + "' strict=" + strict);
         if (!string.contains("&"))
             return string;
         Matcher m = strict? strictUnescapePattern.matcher(string) : unescapePattern.matcher(string);
+        if (string.contains("mid") || string.contains("wr")) System.err.println("DEBUG: using " + (strict ? "strict" : "non-strict") + " pattern");
         StringBuffer accum = new StringBuffer(string.length());
         while (m.find()) {
             int charval = -1;
             String num = m.group(3);
+            String name = null;
             if (num != null) {
                 try {
-                    int base = m.group(2) != null ? 16 : 10;
-                    charval = Integer.valueOf(num, base);
+                    int radix = m.group(2) != null ? 16 : 10;
+                    charval = Integer.valueOf(num, radix);
                 } catch (NumberFormatException e) {
                 }
             } else {
-                String name = m.group(1);
+                name = m.group(1);
                 if (full.containsKey(name))
                     charval = full.get(name);
             }
-            if (charval != -1 || charval > 0xFFFF) {
-                String c = Character.toString((char) charval);
-                m.appendReplacement(accum, Matcher.quoteReplacement(c));
+            boolean valid = charval != -1 && charval <= 0xFFFF;
+            if (valid) {
+                boolean isSemicolonTerminated = m.group(0).endsWith(";");
+                boolean isNumeric = num != null;
+                boolean isInBase = name != null && base.containsKey(name);
+                boolean shouldReplace = strict || isSemicolonTerminated || isNumeric || isInBase;
+                if (shouldReplace) {
+                    String c = Character.toString((char) charval);
+                    m.appendReplacement(accum, Matcher.quoteReplacement(c));
+                } else {
+                    m.appendReplacement(accum, Matcher.quoteReplacement(m.group(0)));
+                }
             } else {
                 m.appendReplacement(accum, Matcher.quoteReplacement(m.group(0)));
             }
